design.css:
/* DOS file-manager colors, framed windows, and clean terminal typography.
   Pane colors follow the Visual tab; the desktop uses a dark cloud backdrop. */
:scope { --tigrana-panel-gap: 12px; --tigrana-workspace-inset: 12px; --tigrana-panel-radius: 4px; --tigrana-panel-shadow: 2px 3px 0 #00000040; --tigrana-workspace-background: #0a1d3b url("assets/midnight-clouds.webp") center / cover no-repeat; }
.app-titlebar { border-bottom: 3px double var(--tigrana-border); }
.note-tab { border-radius: 0; box-shadow: none; }
.note-tab.is-active { background: var(--tigrana-accent); color: var(--tigrana-selected-text); border-color: transparent; }
.pane-header { background: var(--tigrana-editor-text); color: var(--tigrana-background); border-bottom: 3px double var(--tigrana-border); }
.folder-pane, .notes-pane, .unified-tree-pane, .main-pane, .right-sidebar { border: 3px double var(--tigrana-border); }
.pane-resizer { background: transparent; }
.pane-resizer::after { opacity: 0; }
.pane-resizer:hover::after, .pane-resizer:focus-visible::after { opacity: 1; }
.note-title-input { font-weight: 400; letter-spacing: 0.02em; }
.ProseMirror h1, .ProseMirror h2, .ProseMirror h3 { color: var(--tigrana-text); font-weight: 400; text-transform: uppercase; letter-spacing: 0.03em; }
.ProseMirror a { color: var(--tigrana-accent); text-decoration: underline; }
:scope.theme-light .ProseMirror a { color: var(--tigrana-editor-text); }
.ProseMirror blockquote { border-left: 3px double var(--tigrana-accent); color: var(--tigrana-text); }
.ProseMirror pre, .ProseMirror table { border: 3px double var(--tigrana-border); }
.ProseMirror hr { border-top: 3px double var(--tigrana-border); }
.ProseMirror code, .ProseMirror pre { font-family: var(--editor-font-family); }
.toolbar-button, .icon-button { border-radius: 0; box-shadow: none; }

.app-titlebar .note-tab { color: var(--titlebar-contrast); }
.app-titlebar .note-tab.is-active { background: var(--tigrana-highlight-background); color: var(--tigrana-highlight-text); }
.topbar-note-title { font-weight: 400; }

/* Let descriptions wrap in the editor options menu. */
.note-view-dropdown strong { font-weight: 400; }
.note-view-dropdown small { white-space: normal; }
.note-view-menu-label { font-weight: 400; }


/* Keep nested outline headings readable without shrinking at each level. */
.outline-item.level-3, .outline-item.level-4, .outline-item.level-5, .outline-item.level-6 { font-size: var(--tigrana-font-navigation); }

/* White body copy and cyan headings on the dark DOS canvas. */
:scope.theme-dark .pane-header { background: var(--tigrana-border); }
:scope.theme-dark .note-title-input, :scope.theme-dark .ProseMirror h1, :scope.theme-dark .ProseMirror h2, :scope.theme-dark .ProseMirror h3, :scope.theme-dark .ProseMirror h4, :scope.theme-dark .ProseMirror h5, :scope.theme-dark .ProseMirror h6 { color: var(--tigrana-border); }
/* Light mode recalls a Windows 95 word processor: white paper and gray chrome. */
:scope.theme-light { --tigrana-workspace-background: #438ac9 url("assets/daylight-meadow.webp") center / cover no-repeat; --tigrana-panel-radius: 0px; --tigrana-panel-shadow: inset 1px 1px 0 var(--surface-strong), inset -1px -1px 0 var(--tigrana-border), 2px 3px 0 #00000040; }
:scope.theme-light .folder-pane, :scope.theme-light .notes-pane, :scope.theme-light .unified-tree-pane, :scope.theme-light .main-pane, :scope.theme-light .right-sidebar { border: 2px solid; border-color: var(--surface-strong) var(--tigrana-border) var(--tigrana-border) var(--surface-strong); }
:scope.theme-light .pane-header { background: var(--tigrana-accent); color: var(--tigrana-selected-text); border-bottom: 1px solid var(--tigrana-border); }
:scope.theme-light .topbar { background: var(--tigrana-surface); border-bottom: 2px solid; border-color: var(--tigrana-border); box-shadow: inset 0 1px 0 var(--surface-strong), inset 0 -1px 0 var(--surface-strong); }
:scope.theme-light.app-titlebar { border-bottom: 2px solid var(--surface-strong); }
:scope.theme-light.app-titlebar .note-tab.is-active { background: var(--tigrana-surface); color: var(--tigrana-text); border: 2px solid; border-color: var(--surface-strong) var(--tigrana-border) var(--tigrana-border) var(--surface-strong); }
:scope.theme-light .topbar .icon-button { border: 1px solid; border-color: var(--surface-strong) var(--tigrana-border) var(--tigrana-border) var(--surface-strong); background: var(--tigrana-surface); color: var(--tigrana-text); }
:scope.theme-light .note-status-bar { background: var(--tigrana-surface); color: var(--tigrana-text); border: 1px solid; border-color: var(--tigrana-border) var(--surface-strong) var(--surface-strong) var(--tigrana-border); border-radius: 0; box-shadow: none; }
:scope.theme-light .ProseMirror h1, :scope.theme-light .ProseMirror h2, :scope.theme-light .ProseMirror h3 { text-transform: none; letter-spacing: normal; }
:scope.theme-light .ProseMirror a { color: var(--tigrana-accent); }
:scope.theme-light .title-shell { margin-top: 24px; }
